    def validate_ip(self):
        # Simple regex for IPv4 validation
        pattern = re.compile(r"^(?:[0-9]{1,3}\.){3}[0-9]{1,3}$")
        if not pattern.match(self.ip):
            raise ValueError(f"Invalid IP address: {self.ip}")

        # Further check to ensure each octet is between 0 and 255
        for octet in self.ip.split('.'):
            if not 0 <= int(octet) <= 255:
                raise ValueError(f"Invalid IP address: {self.ip}")

    def validate_mac(self):
        # Simple regex for MAC address validation (XX:XX:XX:XX:XX:XX)
        pattern = re.compile(r"^([0-9A-Fa-f]{2}[:-]){5}([0-9A-Fa-f]{2})$")
        if not pattern.match(self.mac):
            raise ValueError(f"Invalid MAC address: {self.mac}")

    def validate_status(self):
        valid_statuses = ["up", "down"]
        if self.status.lower() not in valid_statuses:
            raise ValueError(f"Invalid status. Must be one of {valid_statuses}: {self.status}")

    def validate_speed(self):
        if self.speed_gbps <= 0:
            raise ValueError(f"Speed must be greater than 0: {self.speed_gbps} Gbps")

